/**
 * The declarative conversion registry: one source of truth for what Oleafly
 * can turn into what, which engine does the work, and where the feature
 * lives in the app. Three things are driven from this file:
 *
 *   1. the Import and Export menus (see src/components/layout and
 *      src/features/import-export),
 *   2. the pandoc route table the Rust backend executes (mirrored in
 *      src-tauri/src/conversion.rs and pinned together by tests on both
 *      sides),
 *   3. docs/conversion-matrix.md, regenerated by
 *      `pnpm gen:conversion-matrix`.
 *
 * Keep entries ordered by source format, then target. Every matrix cell is
 * either available, existing (shipped before the registry), or deferred with
 * a gap id and a one-line reason.
 */

export type TargetFormat =
  | "pdf"
  | "docx"
  | "html"
  | "markdown"
  | "latex"
  | "typst"
  | "bibtex"
  | "image";

export type SourceFormat =
  | "latex"
  | "markdown"
  | "typst"
  | "docx"
  | "html"
  | "pdf"
  | "image"
  | "csv"
  | "arxiv"
  | "doi"
  | "isbn"
  | "pmid"
  | "ris"
  | "endnote"
  | "zotero"
  | "bibtex";

export type ConversionEngine =
  | "pandoc"
  | "tectonic"
  | "typst"
  | "pdf-pipeline"
  | "api-lookup"
  | "internal";

export type RouteStatus = "available" | "existing" | "deferred";

export interface ConversionRoute {
  /** Stable id used by tests, docs links, and the backend mirror. */
  id: string;
  /** Short label for menus. */
  label: string;
  /** One sentence for the docs matrix. */
  blurb: string;
  source: SourceFormat;
  target: TargetFormat;
  /** import creates a project or library entry; export writes a file from an open project; tool runs on demand. */
  direction: "import" | "export" | "tool";
  engine: ConversionEngine;
  status: RouteStatus;
  /** Where the feature lives in the app. */
  surface: string;
  /** The gap this route closes (gap-analysis.md G-id), when it came from one. */
  gapId?: string;
  /** Required when status is "deferred". */
  deferredReason?: string;
  /** File extensions the Import dialog offers for import routes. */
  extensions?: string[];
  /** For pandoc routes: the reader and writer the backend uses. */
  pandoc?: { from: string; to: string; flags?: string[] };
}

type PandocRouteOptions = Readonly<{
  direction?: "import" | "export";
  extensions?: readonly string[] | false;
  flags?: readonly string[];
  plan?: false;
  surface?: string;
  writer?: string;
}>;

type PandocRouteEntry = readonly [
  id: string,
  label: string,
  blurb: string,
  target: TargetFormat,
  status: RouteStatus,
  gapId?: string,
  options?: PandocRouteOptions,
];

const PANDOC_READERS = {
  docx: "docx",
  html: "html",
  latex: "latex",
  markdown: "markdown",
  typst: "typst",
} as const;

const PANDOC_WRITERS: Record<TargetFormat, string> = {
  bibtex: "bibtex",
  docx: "docx",
  html: "html5",
  image: "image",
  latex: "latex",
  markdown: "markdown",
  pdf: "pdf",
  typst: "typst",
};

const PANDOC_STANDALONE = ["--standalone"];
const PANDOC_HTML = ["--standalone", "--embed-resources", "--mathml"];
const PANDOC_EXTRACT_MEDIA = ["--standalone", "--extract-media=assets"];

function pandocRoutes(
  source: keyof typeof PANDOC_READERS,
  entries: readonly PandocRouteEntry[],
  defaults: Readonly<{ direction: "import" | "export"; extensions?: readonly string[] }>,
): ConversionRoute[] {
  return entries.map(([id, label, blurb, target, status, gapId, options]) => {
    const direction = options?.direction ?? defaults.direction;
    const extensions = options?.extensions === false
      ? undefined
      : options?.extensions ?? defaults.extensions;
    const route: ConversionRoute = {
      id,
      label,
      blurb,
      source,
      target,
      direction,
      engine: "pandoc",
      status,
      surface: options?.surface ?? (direction === "import" ? "Import dialog" : "Export menu"),
    };
    if (gapId) route.gapId = gapId;
    if (extensions) route.extensions = [...extensions];
    if (options?.plan !== false) {
      route.pandoc = {
        from: PANDOC_READERS[source],
        to: options?.writer ?? PANDOC_WRITERS[target],
        ...(options?.flags ? { flags: [...options.flags] } : {}),
      };
    }
    return route;
  });
}

