/** Routes that create new projects, in menu order. */
export function importRoutes(): readonly ConversionRoute[] {
  return REGISTRY.filter(
    (route) =>
      route.direction === "import" &&
      route.status !== "deferred" &&
      route.extensions !== undefined,
  );
}

/** Find the import route matching a picked file extension and chosen target. */
export function importRouteFor(
  extension: string,
  target: string,
): ConversionRoute | undefined {
  return REGISTRY.find(
    (route) =>
      route.direction === "import" &&
      route.status !== "deferred" &&
      route.extensions?.includes(extension) &&
      targetForRoute(route) === target,
  );
}

function targetForRoute(route: ConversionRoute): string | undefined {
  switch (route.target) {
    case "latex":
      return "latex";
    case "markdown":
      return "markdown";
    case "typst":
      return "typst";
    default:
      return undefined;
  }
}

/** Export formats an engine can write, in menu order. */
export function exportRoutesFor(
  engineId: string,
  exports: readonly string[],
): readonly ConversionRoute[] {
  const sourcesByEngine: Record<string, SourceFormat[]> = {
    latex: ["latex"],
    latexmk: ["latex"],
    typst: ["typst"],
    markdown: ["markdown"],
  };
  const sources = sourcesByEngine[engineId];
  if (!sources) {
    return [];
  }
  // Menu order per engine; "tex"/"md" are the backend's export format ids
  // for LaTeX/Markdown targets.
  const order: Record<string, string[]> = {
    latex: ["pdf", "docx", "html", "md", "typst", "txt", "pptx", "epub"],
    latexmk: ["pdf", "docx", "html", "md", "typst", "txt", "pptx", "epub"],
    typst: ["pdf", "tex", "docx", "html", "md", "txt"],
    markdown: ["pdf", "docx", "html", "typst", "tex", "txt", "pptx", "epub"],
  };
  const targetForFormat: Record<string, TargetFormat> = {
    pdf: "pdf",
    docx: "docx",
    html: "html",
    md: "markdown",
    typst: "typst",
    tex: "latex",
  };
  const routes: ConversionRoute[] = [];
  for (const format of order[engineId] ?? []) {
    if (!exports.includes(format)) {
      continue;
    }
    const target = targetForFormat[format];
    // Bidirectional routes (import a file, or export from that engine's
    // project) qualify through their source, whichever menu they list first.
    const route = REGISTRY.find(
      (candidate) =>
        candidate.direction !== "tool" &&
        candidate.status !== "deferred" &&
        sources.includes(candidate.source) &&
        candidate.target === target,
    );
    if (route && !routes.some((existing) => existing.id === route.id)) {
      routes.push(route);
    }
  }
  return routes;
}

/** Every deferred route, for docs and planning. */
export function deferredRoutes(): readonly ConversionRoute[] {
  return REGISTRY.filter((route) => route.status === "deferred");
}
